[ExtensionOf(classStr(PriceDiscAdmCheckPost))]
final class METPriceDiscAdmCheckPost_Extension
{
}

Method.Source:
    /// <summary>
    /// post Journal extension
    /// </summary>
    void postJournal()
    {
        next postJournal();

        if(this.isPosted())
        {
            PriceDiscAdmTable priceDiscAdmTable = PriceDiscAdmTable::find(journalNum);

            Global::runAsync(classNum(METPriceChangeTrackManage),
                            staticMethodStr(METPriceChangeTrackManage, trackChange),
                            [METPriceChangeType::TradeAgreement, priceDiscAdmTable],
                            System.Threading.CancellationToken::None,
                            classNum(METPriceChangeTrackManage),
                            staticMethodStr(METPriceChangeTrackManage, callBackResult));
        }
    }
